args.sql:
SELECT DISTINCT distinct_visa_types FROM (
    SELECT ca.counselmail, COUNT(DISTINCT c.visacls) as distinct_visa_types
    FROM case_attorney ca
    JOIN cases c ON ca.docketkey = c.filekey
    GROUP BY ca.counselmail
) sub ORDER BY distinct_visa_types;

